#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long n_value, total_nodes, total_sum, result_sum;
vector<long long> storage[15];

void build_tree(int level, long long num);
void evaluate(long long x);

int main() {
    cin >> n_value;
    build_tree(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(storage[i].begin(), storage[i].end());
    }
    total_nodes = 0;
    for (long long i = 1; i <= 9; ++i) {
        evaluate(i);
    }
    cout << result_sum << "\n";
    return 0;
}

void build_tree(int level, long long num) {
    if (level == 7) return;
    total_nodes++;
    long long val = ((total_nodes - num) % 998244353 + 998244353) % 998244353;
    storage[level].push_back(val);
    total_sum = (total_sum + val) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        build_tree(level + 1, num * 10 + digit);
    }
}

void evaluate(long long x) {
    if (x > n_value) return;
    if (x * 1000000 + 999999 <= n_value && x * 10000000 > n_value) {
        long long current_total = total_nodes;
        for (int i = 0, factor = 1; i <= 6; ++i, factor *= 10) {
            int size = storage[i].size();
            long long diff = ((current_total - x * factor) % 998244353 + 998244353) % 998244353;
            int pos = (int)(lower_bound(storage[i].begin(), storage[i].end(), 1000000000 - diff) - storage[i].begin());
            result_sum = (result_sum + diff * size + total_sum) % 1000000007;
            result_sum = (result_sum - 998244353 * (size - pos) % 1000000007 + 1000000007) % 1000000007;
            current_total += size;
        }
        return;
    }
    total_nodes++;
    result_sum = (result_sum + ((total_nodes - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        evaluate(x * 10 + digit);
    }
}
